update btw_prompts set text = 'Последний вопрос: ваша церковь участвует в Baptize 2027 и мы можем связаться с вами об этом? Ответьте ДА.', updated_at = now() where key = 'ask_consent' and lang = 'ru';
update btw_prompts set text = 'آخری سوال: کیا آپ کا چرچ Baptize 2027 میں شامل ہے اور ہم اس بارے میں آپ سے رابطہ کر سکتے ہیں؟ ہاں لکھیں۔', updated_at = now() where key = 'ask_consent' and lang = 'ur';
